<?php
declare(strict_types=1);session_start();require_once __DIR__.'/config/sales_step15.php';if(empty($_SESSION['follow15_csrf']))$_SESSION['follow15_csrf']=bin2hex(random_bytes(24));$csrf=(string)$_SESSION['follow15_csrf'];$error=null;$success=null;$rows=[];$filter=(string)($_GET['filter']??'open');
try{$pdo=business_db();sales_step15_ensure($pdo);sales_step15_backfill($pdo);$ctx=sales_step15_context($pdo);$orgId=(int)$ctx['organization_id'];if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($csrf,(string)($_POST['csrf']??'')))throw new RuntimeException('Security token mismatch.');sales_step15_complete_interaction($pdo,(int)$_POST['interaction_id']);$success='Follow-up marked complete.';}$sql="SELECT i.*,c.customer_name,c.mobile FROM crm_interactions i JOIN crm_customers c ON c.id=i.customer_id AND c.organization_id=i.organization_id WHERE i.organization_id=?";$args=[$orgId];if($filter==='due'){$sql.=" AND i.status='open' AND i.next_followup_at IS NOT NULL AND i.next_followup_at<=NOW()";}elseif($filter==='upcoming'){$sql.=" AND i.status='open' AND i.next_followup_at>NOW()";}elseif($filter==='done'){$sql.=" AND i.status='done'";}else{$filter='open';$sql.=" AND i.status='open'";}$sql.=" ORDER BY CASE WHEN i.next_followup_at IS NULL THEN 1 ELSE 0 END,i.next_followup_at,i.id DESC LIMIT 200";$stmt=$pdo->prepare($sql);$stmt->execute($args);$rows=$stmt->fetchAll();}catch(Throwable $e){$error=$e->getMessage();}
function cf_h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>CRM Follow-ups - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="customer_center.php"><img src="../img/logo.png" alt="logo"><span><strong>Healthcare Wellness Club</strong><small>STEP 15 • CRM Follow-ups</small></span></a><div class="os-top-actions"><a class="os-btn" href="customer_center.php">Customers</a><a class="os-btn" href="sales_receivables.php">Receivables</a><a class="os-btn primary" href="sales_fulfillment.php">Fulfillment</a></div></div></header><div class="os-layout"><aside class="os-sidebar"><div class="os-nav-label">CRM</div><nav class="os-nav"><a href="customer_center.php"><i class="dot"></i>Customers</a><a href="sales_fulfillment.php"><i class="dot"></i>Fulfillment</a><a class="active" href="crm_followups.php"><i class="dot"></i>Follow-ups</a><a href="sales_receivables.php"><i class="dot"></i>Receivables</a><a href="sales_analytics_step15.php"><i class="dot"></i>Analytics</a></nav></aside><main class="os-main"><section class="os-hero pp-hero"><div class="os-kicker">STEP 15H • CRM FOLLOW-UP QUEUE</div><h1>Keep customer conversations and next actions visible.</h1><p>Follow-ups come from Customer 360° interactions and remain auditable when completed.</p><div class="os-status-row"><span class="os-chip <?= $error===null?'good':'' ?>"><?= $error===null?'FOLLOW-UP CENTER LIVE':'Review required' ?></span><span class="os-chip"><?= count($rows) ?> <?= cf_h($filter) ?> items</span></div></section><?php if($error):?><div class="pp-alert bad"><strong>Follow-up diagnostic:</strong> <?= cf_h($error) ?></div><?php endif;?><?php if($success):?><div class="pp-alert good"><strong>Done:</strong> <?= cf_h($success) ?></div><?php endif;?><?php if(!$error):?><section class="os-card" style="margin-top:14px"><div class="pp-actions"><a href="?filter=open">Open</a><a href="?filter=due">Due</a><a href="?filter=upcoming">Upcoming</a><a href="?filter=done">Done</a></div><div class="pp-table-wrap" style="margin-top:12px"><table class="pp-table"><thead><tr><th>Customer</th><th>Type</th><th>Interaction</th><th>Next Follow-up</th><th>Sale</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><a href="customer_detail.php?id=<?= (int)$r['customer_id'] ?>"><b><?= cf_h($r['customer_name']) ?></b></a><small><?= cf_h($r['mobile']?:'') ?></small></td><td><?= cf_h(strtoupper($r['interaction_type'])) ?></td><td><b><?= cf_h($r['subject']?:'CRM activity') ?></b><small><?= cf_h($r['notes']) ?></small></td><td><?= cf_h($r['next_followup_at']?substr($r['next_followup_at'],0,16):'—') ?></td><td><?= $r['order_id']?'#'.(int)$r['order_id']:'—' ?></td><td><?= cf_h(strtoupper($r['status'])) ?></td><td><?php if($r['status']==='open'):?><form method="post"><input type="hidden" name="csrf" value="<?= cf_h($csrf) ?>"><input type="hidden" name="interaction_id" value="<?= (int)$r['id'] ?>"><button>Mark Done</button></form><?php endif;?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="7">No matching CRM follow-ups.</td></tr><?php endif;?></tbody></table></div></section><?php endif;?><div class="os-footer-note"><strong>CRM rule:</strong> completing a follow-up changes status only; the original interaction and notes remain preserved.</div></main></div><script src="assets/business-collapsible.js?v=20260820-1" defer></script></body></html>
